#!/bin/sh
set -eu

vmstat_file=/proc/vmstat
psi_file=/proc/pressure/memory
boot_id_file=/proc/sys/kernel/random/boot_id

[ -r "$vmstat_file" ] && [ -r "$boot_id_file" ]
page_size_bytes=$(getconf PAGE_SIZE)
boot_id=$(tr -d '\n' < "$boot_id_file")

vm_fields=$(awk '
  $1 == "pswpin"  { pin=$2 }
  $1 == "pswpout" { pout=$2 }
  END {
    if (pin == "" || pout == "") exit 1
    printf "pswpin_pages=%s pswpout_pages=%s", pin, pout
  }
' "$vmstat_file")

psi_fields="psi_available=0"
if [ -r "$psi_file" ]; then
  psi_fields=$(awk '
    $1 == "some" {
      for (i=2; i<=NF; i++) { split($i, a, "="); if (a[1] == "avg10") savg=a[2]; if (a[1] == "total") stotal=a[2] }
    }
    $1 == "full" {
      for (i=2; i<=NF; i++) { split($i, a, "="); if (a[1] == "avg10") favg=a[2]; if (a[1] == "total") ftotal=a[2] }
    }
    END {
      if (savg == "" || stotal == "" || favg == "" || ftotal == "") exit 1
      printf "psi_available=1 psi_some_avg10_pct=%s psi_full_avg10_pct=%s psi_some_total_us=%s psi_full_total_us=%s", savg, favg, stotal, ftotal
    }
  ' "$psi_file")
fi

printf 'boot_id=%s page_size_bytes=%s %s %s\n' "$boot_id" "$page_size_bytes" "$vm_fields" "$psi_fields"
